/**
 * FreeLang v2 Phase 11: Feedback Analyzer
 * 사용자 피드백을 분석하여 AI 패턴 신뢰도 개선
 *
 * 역할: 긍정/부정 피드백 수집 및 분석
 */

interface UserFeedback {
  patternId: string;
  timestamp: Date;
  helpful: boolean;
  rating: number; // 1-5
  comment?: string;
  context?: string;
}

interface FeedbackMetrics {
  totalFeedback: number;
  helpfulCount: number;
  unhelpfulCount: number;
  averageRating: number;
  successRate: number;
  trends: {
    lastWeek: number;
    lastMonth: number;
    allTime: number;
  };
}

class FeedbackAnalyzer {
  private feedbackStore: Map<string, UserFeedback[]> = new Map();
  private metrics: Map<string, FeedbackMetrics> = new Map();

  /**
   * 피드백 수집
   */
  collectFeedback(feedback: UserFeedback): void {
    const patternId = feedback.patternId;

    if (!this.feedbackStore.has(patternId)) {
      this.feedbackStore.set(patternId, []);
    }

    this.feedbackStore.get(patternId)!.push(feedback);
    this.updateMetrics(patternId);
  }

  /**
   * 메트릭 업데이트
   */
  private updateMetrics(patternId: string): void {
    const feedbacks = this.feedbackStore.get(patternId) || [];

    const helpfulCount = feedbacks.filter(f => f.helpful).length;
    const unhelpfulCount = feedbacks.filter(f => !f.helpful).length;
    const averageRating = feedbacks.length > 0
      ? feedbacks.reduce((sum, f) => sum + f.rating, 0) / feedbacks.length
      : 0;

    const now = new Date();
    const oneWeekAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
    const oneMonthAgo = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);

    const lastWeekFeedback = feedbacks.filter(f => f.timestamp > oneWeekAgo);
    const lastMonthFeedback = feedbacks.filter(f => f.timestamp > oneMonthAgo);

    const metrics: FeedbackMetrics = {
      totalFeedback: feedbacks.length,
      helpfulCount,
      unhelpfulCount,
      averageRating,
      successRate: feedbacks.length > 0 ? helpfulCount / feedbacks.length : 0,
      trends: {
        lastWeek: lastWeekFeedback.length,
        lastMonth: lastMonthFeedback.length,
        allTime: feedbacks.length
      }
    };

    this.metrics.set(patternId, metrics);
  }

  /**
   * 패턴별 메트릭 조회
   */
  getMetrics(patternId: string): FeedbackMetrics | null {
    return this.metrics.get(patternId) || null;
  }

  /**
   * 전체 메트릭 조회
   */
  getAllMetrics(): Map<string, FeedbackMetrics> {
    return new Map(this.metrics);
  }

  /**
   * 성공률 계산
   */
  calculateSuccessRate(patternId: string): number {
    const feedbacks = this.feedbackStore.get(patternId) || [];
    if (feedbacks.length === 0) return 0;

    const helpfulCount = feedbacks.filter(f => f.helpful).length;
    return helpfulCount / feedbacks.length;
  }

  /**
   * 신뢰도 가중치 계산 (0.0 - 1.0)
   * 피드백 기반 신뢰도 조정
   */
  calculateConfidenceWeight(patternId: string): number {
    const metrics = this.metrics.get(patternId);
    if (!metrics) return 0.5; // 기본값

    const successWeight = metrics.successRate * 0.6;
    const ratingWeight = (metrics.averageRating / 5) * 0.3;
    const volumeWeight = Math.min(metrics.totalFeedback / 100, 1) * 0.1;

    return successWeight + ratingWeight + volumeWeight;
  }

  /**
   * 피드백 요약 생성
   */
  generateSummary(patternId: string): object {
    const metrics = this.metrics.get(patternId);
    const feedbacks = this.feedbackStore.get(patternId) || [];

    if (!metrics) {
      return {
        patternId,
        status: 'no-feedback',
        message: '아직 피드백이 없습니다'
      };
    }

    return {
      patternId,
      status: 'analyzed',
      metrics: {
        totalFeedback: metrics.totalFeedback,
        successRate: (metrics.successRate * 100).toFixed(2) + '%',
        averageRating: metrics.averageRating.toFixed(2),
        confidenceWeight: (this.calculateConfidenceWeight(patternId) * 100).toFixed(2) + '%'
      },
      trends: metrics.trends,
      recentComments: feedbacks
        .filter(f => f.comment)
        .slice(-3)
        .map(f => ({
          helpful: f.helpful,
          rating: f.rating,
          comment: f.comment,
          timestamp: f.timestamp
        }))
    };
  }

  /**
   * 문제가 있는 패턴 찾기
   */
  findProblematicPatterns(threshold: number = 0.5): string[] {
    const problematic: string[] = [];

    for (const [patternId, metrics] of this.metrics) {
      if (metrics.successRate < threshold && metrics.totalFeedback >= 5) {
        problematic.push(patternId);
      }
    }

    return problematic;
  }

  /**
   * 우수 패턴 찾기
   */
  findExcellingPatterns(threshold: number = 0.8): string[] {
    const excelling: string[] = [];

    for (const [patternId, metrics] of this.metrics) {
      if (metrics.successRate >= threshold && metrics.totalFeedback >= 5) {
        excelling.push(patternId);
      }
    }

    return excelling;
  }

  /**
   * 패턴 비교
   */
  comparePatterns(patternId1: string, patternId2: string): object {
    const metrics1 = this.metrics.get(patternId1);
    const metrics2 = this.metrics.get(patternId2);

    return {
      pattern1: {
        id: patternId1,
        successRate: metrics1?.successRate || 0,
        averageRating: metrics1?.averageRating || 0,
        totalFeedback: metrics1?.totalFeedback || 0
      },
      pattern2: {
        id: patternId2,
        successRate: metrics2?.successRate || 0,
        averageRating: metrics2?.averageRating || 0,
        totalFeedback: metrics2?.totalFeedback || 0
      },
      winner: {
        bySuccessRate: (metrics1?.successRate || 0) > (metrics2?.successRate || 0) ? patternId1 : patternId2,
        byRating: (metrics1?.averageRating || 0) > (metrics2?.averageRating || 0) ? patternId1 : patternId2
      }
    };
  }

  /**
   * 피드백 내보내기 (분석용)
   */
  exportFeedback(patternId: string): object {
    const feedbacks = this.feedbackStore.get(patternId) || [];

    return {
      patternId,
      count: feedbacks.length,
      data: feedbacks.map(f => ({
        timestamp: f.timestamp.toISOString(),
        helpful: f.helpful,
        rating: f.rating,
        comment: f.comment || null,
        context: f.context || null
      }))
    };
  }

  /**
   * 분석 리포트 생성
   */
  generateReport(): object {
    const report = {
      generatedAt: new Date().toISOString(),
      totalPatterns: this.metrics.size,
      patternStats: {
        excellent: this.findExcellingPatterns(0.9).length,
        good: this.findExcellingPatterns(0.7).length - this.findExcellingPatterns(0.9).length,
        problematic: this.findProblematicPatterns(0.5).length
      },
      globalMetrics: {
        avgSuccessRate: this.calculateGlobalSuccessRate(),
        avgRating: this.calculateGlobalAverageRating(),
        totalFeedbackCollected: this.calculateTotalFeedback()
      },
      topPatterns: this.getTopPatterns(5),
      bottomPatterns: this.getBottomPatterns(5)
    };

    return report;
  }

  /**
   * 전역 성공률 계산
   */
  private calculateGlobalSuccessRate(): string {
    let totalHelpful = 0;
    let totalFeedback = 0;

    for (const feedbacks of this.feedbackStore.values()) {
      totalFeedback += feedbacks.length;
      totalHelpful += feedbacks.filter(f => f.helpful).length;
    }

    const rate = totalFeedback > 0 ? (totalHelpful / totalFeedback) * 100 : 0;
    return rate.toFixed(2) + '%';
  }

  /**
   * 전역 평균 레이팅 계산
   */
  private calculateGlobalAverageRating(): string {
    let totalRating = 0;
    let totalFeedback = 0;

    for (const feedbacks of this.feedbackStore.values()) {
      totalFeedback += feedbacks.length;
      totalRating += feedbacks.reduce((sum, f) => sum + f.rating, 0);
    }

    const avg = totalFeedback > 0 ? totalRating / totalFeedback : 0;
    return avg.toFixed(2);
  }

  /**
   * 전체 피드백 수 계산
   */
  private calculateTotalFeedback(): number {
    let total = 0;
    for (const feedbacks of this.feedbackStore.values()) {
      total += feedbacks.length;
    }
    return total;
  }

  /**
   * 상위 패턴 조회
   */
  private getTopPatterns(limit: number): Array<{patternId: string; successRate: number}> {
    const sorted = Array.from(this.metrics.entries())
      .sort((a, b) => b[1].successRate - a[1].successRate)
      .slice(0, limit)
      .map(([patternId, metrics]) => ({
        patternId,
        successRate: metrics.successRate
      }));

    return sorted;
  }

  /**
   * 하위 패턴 조회
   */
  private getBottomPatterns(limit: number): Array<{patternId: string; successRate: number}> {
    const sorted = Array.from(this.metrics.entries())
      .sort((a, b) => a[1].successRate - b[1].successRate)
      .slice(0, limit)
      .map(([patternId, metrics]) => ({
        patternId,
        successRate: metrics.successRate
      }));

    return sorted;
  }
}

module.exports = { FeedbackAnalyzer };

