    68→ */
    69→export class FeedbackAnalyzer {
    70→  private patterns: Map<string, IntentPattern>;
    71→  private uniquePatterns: Map<string, IntentPattern>; // Track unique patterns by ID
    72→  private feedbackByPattern: Map<string, FeedbackEntry[]>;
    73→
    74→  constructor(allPatterns: IntentPattern[]) {
    75→    // Index patterns by name and aliases for quick lookup
    76→    this.patterns = new Map();
    77→    this.uniquePatterns = new Map();
    78→
    79→    for (const pattern of allPatterns) {
    80→      this.patterns.set(pattern.name, pattern);
    81→      this.uniquePatterns.set(pattern.id, pattern);
    82→
    83→      // Also index by aliases for flexible matching
    84→      for (const alias of pattern.aliases) {
