## ✅ Phase 4: 프론트엔드 구성 (React + freelang-hybrid)

### 4.1 Blog List Component

```typescript
import { useFreeLang } from '@/bridge/hooks';
import { useAsyncAction } from '@/bridge/hooks';

function BlogList() {
  const [blogs, dispatch] = useFreeLang('blogs');
  const [filters] = useFreeLang('filters');

  const { loading, execute } = useAsyncAction(async () => {
    const response = await fetch(`/api/blog?category=${filters.category}`);
    return response.json();
  });

  useEffect(() => {
    execute().then(data => {
      dispatch('blog/fetch', data);
    });
  }, [filters]);

  if (loading) return <div>Loading...</div>;

  return (
    <div className="blog-list">
      {blogs.map(blog => (
        <BlogCard key={blog.id} blog={blog} />
      ))}
    </div>
  );
}
```

### 4.2 Blog Editor Component

```typescript
function BlogEditor({ blogId }) {
  const [blog, setBlog] = useState(null);
  const [isDraft, setIsDraft] = useState(true);
  const [isSaving, setIsSaving] = useState(false);

  const handleSave = async () => {
    setIsSaving(true);
    const method = blogId ? 'PATCH' : 'POST';
    const url = blogId ? `/api/blog/${blogId}` : '/api/blog';

    const response = await fetch(url, {
      method,
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(blog)
    });

    if (response.ok) {
      setIsDraft(false);
      // Update state
    }
    setIsSaving(false);
  };

  return (
    <form onSubmit={handleSave}>
      <input name="title" />
      <textarea name="content" />
      <select name="category">
        <option>Tech</option>
        <option>Design</option>
      </select>
      <button type="submit" disabled={isSaving}>
        {isDraft ? 'Save Draft' : 'Update'}
      </button>
    </form>
  );
}
```

